import math

def check_solution(b):
    """Checks for integer solutions a given b."""
    # Equation: a^2 - (2^(b+1)-1)a + 2*3^b = 0
    D = (2**(b+1)) - 1

    # Discriminant: Delta = D^2 - 8 * 3^b
    Delta = D**2 - 8 * (3**b)

    if Delta < 0:
        return []

    S = math.isqrt(Delta)

    if S * S == Delta:
        # Solutions for a: a = (D +/- S) / 2

        solutions = []

        # Check a1
        if (D + S) % 2 == 0:
            a1 = (D + S) // 2
            if a1 > 0:
                solutions.append(a1)

        # Check a2
        if (D - S) % 2 == 0:
            a2 = (D - S) // 2
            if a2 > 0:
                solutions.append(a2)

        return solutions
    else:
        return []

solutions_list = []
max_b = 10 # Check up to b=10
for b in range(1, max_b + 1):
    solutions_a = check_solution(b)
    if solutions_a:
        for a in solutions_a:
            solutions_list.append((a, b))

print("Found Solutions (a, b):")
for sol in solutions_list:
    print(sol)

total_sum = sum(a + b for a, b in solutions_list)
print(f"Total sum of (a+b) for b <= {max_b}: {total_sum}")

